   "theme": "bijwoord",
   "rule": "Gebruik ¿QUÉ? om naar iets in het algemeen te vragen en ¿CUÁL/CUÁLES? om te kiezen binnen een gekende groep, nooit vóór een zelfstandig naamwoord.",
